const fs=require('fs');
const css=fs.readFileSync('build/tokens.css','utf8');
function block(re){const m=css.match(re); if(!m)return {}; const o={}; for(const l of m[1].split(';')){const i=l.indexOf(':'); if(i<0)continue; const k=l.slice(0,i).trim(); const v=l.slice(i+1).trim(); if(k.startsWith('--'))o[k]=v;} return o;}
const light=block(/:root \{([\s\S]*?)\n\}/);
const hasExplicitDark=Object.entries(light).filter(([k,v])=>v.startsWith('var('));
console.log('light vars',Object.keys(light).length);
console.log('ref vars (alias)',hasExplicitDark.length);
for(const [k,v] of hasExplicitDark.slice(0,20))console.log(k,'=',v);
"

