import fs from 'node:fs';
import path from 'node:path';

const DESIGN = '/Users/michael/Development/michaelkrog/Pathland/design';
const OUT = '/var/folders/5p/0d4szgs13t5b74h2c379j3gc0000gn/T/opencode/pathland-design';

const css = fs.readFileSync(path.join(DESIGN, 'build/tokens.css'), 'utf8');
const manifest = JSON.parse(fs.readFileSync(path.join(DESIGN, 'build/manifest.json'), 'utf8'));

function parseBlock(re) {
  const m = css.match(re);
  const out = {};
  if (!m) return out;
  for (const decl of m[1].split(';')) {
    const i = decl.indexOf(':');
    if (i < 0) continue;
    const k = decl.slice(0, i).trim();
    const v = decl.slice(i + 1).trim();
    if (k.startsWith('--')) out[k] = v;
  }
  return out;
}

const light = parseBlock(/:root \{([\s\S]*?)\n\}/);
const dark = parseBlock(/:root\[data-pathland-scheme='dark'\] \{([\s\S]*?)\n\}/);

function resolve(block, cssVar, seen = 0) {
  const raw = block[cssVar];
  if (raw == null) return null;
  const alias = raw.match(/^var\((--[^)]+)\)$/);
  if (alias) {
    if (seen > 20) throw new Error('alias loop ' + cssVar);
    return resolve(block, alias[1], seen + 1);
  }
  return raw;
}

function parseColor(v) {
  v = v.trim();
  if (v.startsWith('#')) {
    let h = v.slice(1);
    if (h.length === 3) h = h.split('').map((c) => c + c).join('');
    if (h.length === 6) h += 'ff';
    if (h.length === 8) {
      return {
        r: parseInt(h.slice(0, 2), 16) / 255,
        g: parseInt(h.slice(2, 4), 16) / 255,
        b: parseInt(h.slice(4, 6), 16) / 255,
        a: parseInt(h.slice(6, 8), 16) / 255,
      };
    }
  }
  const m = v.match(/^rgba?\(([^)]*)\)$/i);
  if (m) {
    const parts = m[1].replace('/', ' ').trim().split(/[\s,]+/).filter(Boolean);
    const num = (x, scale = 1) => (x.endsWith('%') ? parseFloat(x) / 100 : parseFloat(x) / scale);
    return {
      r: num(parts[0], 255),
      g: num(parts[1], 255),
      b: num(parts[2], 255),
      a: parts[3] == null ? 1 : num(parts[3]),
    };
  }
  throw new Error('unparsed color: ' + v);
}

function parseFloatValue(v) {
  const m = String(v).trim().match(/^(-?[\d.]+)([a-z%]*)$/i);
  if (!m) throw new Error('unparsed number: ' + v);
  const n = parseFloat(m[1]);
  const unit = m[2].toLowerCase();
  if (unit === 'rem' || unit === 'em') return round(n * 16);
  if (unit === 'ms') return round(n);
  if (unit === 's') return round(n * 1000);
  return round(n);
}

function round(n) {
  return Math.round(n * 1000) / 1000;
}

function convert(raw, type) {
  if (raw == null) throw new Error('missing value');
  if (type === 'color') return { kind: 'COLOR', value: parseColor(raw) };
  if (type === 'fontFamily' || type === 'string') return { kind: 'STRING', value: String(raw).trim() };
  return { kind: 'FLOAT', value: parseFloatValue(raw) };
}

// emitted tokens
const emitted = manifest.map((t) => {
  const l = resolve(light, t.cssVar);
  const d = resolve(dark, t.cssVar) ?? l;
  const lc = convert(l, t.type);
  const dc = convert(d, t.type);
  if (lc.kind !== dc.kind) throw new Error('type mismatch ' + t.path);
  return {
    name: t.path,
    type: lc.kind,
    light: lc.value,
    dark: dc.value,
    description: `${t.layer} token${t.internal ? ' (internal)' : ''} — ${t.cssVar}`,
  };
});

// base tokens
const baseFiles = fs.readdirSync(path.join(DESIGN, 'tokens/base')).filter((f) => f.endsWith('.json'));
const baseMap = {};
for (const f of baseFiles) Object.assign(baseMap, JSON.parse(fs.readFileSync(path.join(DESIGN, 'tokens/base', f), 'utf8')));

function resolveBase(key, seen = 0) {
  if (seen > 20) throw new Error('base ref loop ' + key);
  const entry = baseMap[key];
  if (!entry) throw new Error('missing base token ' + key);
  const raw = entry.$value;
  if (typeof raw === 'string') {
    const ref = raw.match(/^\{([^}]+)\}$/);
    if (ref) return resolveBase(ref[1], seen + 1);
  }
  return { raw, type: entry.$type };
}

const base = Object.keys(baseMap).sort().map((key) => {
  const { raw, type } = resolveBase(key);
  const c = convert(raw, type);
  return {
    name: key,
    type: c.kind,
    value: c.value,
    description: `base token (internal) — ${type}`,
  };
});

const data = { emitted, base };
const js = `// generated token bootstrap
const DATA = ${JSON.stringify(data)};
const g = figma.graph;
const COLLECTIONS = { emitted: 'Pathland Tokens', base: 'Base Palette' };

function removeExisting(name) {
  for (const c of [...g.variableCollections.values()]) {
    if (c.name === name) g.removeCollection(c.id);
  }
}

function makeCollection(name, modeNames) {
  removeExisting(name);
  const c = g.createCollection(name);
  const modes = c.modes.map((m) => m.modeId);
  g.renameMode(c.id, modes[0], modeNames[0]);
  const ids = [modes[0]];
  for (let i = 1; i < modeNames.length; i++) ids.push(g.createMode(c.id, modeNames[i]));
  return { id: c.id, modes: ids };
}

const emittedCol = makeCollection(COLLECTIONS.emitted, ['Light', 'Dark']);
const baseCol = makeCollection(COLLECTIONS.base, ['Value']);

for (const t of DATA.emitted) {
  const v = g.createVariable(t.name, t.type, emittedCol.id, t.light);
  v.description = t.description;
  v.valuesByMode[emittedCol.modes[1]] = t.dark;
}
for (const t of DATA.base) {
  const v = g.createVariable(t.name, t.type, baseCol.id, t.value);
  v.description = t.description;
}
return {
  emitted: DATA.emitted.length,
  base: DATA.base.length,
  emittedCollection: emittedCol.id,
  baseCollection: baseCol.id,
};
`;

fs.writeFileSync(path.join(OUT, 'tokens-eval.js'), js);
fs.writeFileSync(path.join(OUT, 'tokens.json'), JSON.stringify(data, null, 2));
console.log('wrote tokens-eval.js', emitted.length, 'emitted,', base.length, 'base');

