  success: '#16a34a', warning: '#d97706', danger: '#dc2626', info: '#2563eb',
  elevationLow: '0 1 2 #0000000d', elevationHigh: '0 4 12 #00000026',
};

const D = {
  bg: '#0f172a', surface: '#111827', textPrimary: '#f9fafb', textSecondary: '#9ca3af',
  border: '#374151', separator: '#374151', controlBg: '#ffffff1a', controlBgHover: '#ffffff33',
  controlBorder: '#ffffff26', controlFg: '#f9fafb', primary: '#60a5fa', secondary: '#818cf8',
  accent: '#60a5fa', inputBg: '#ffffff0d', inputBorder: '#ffffff1a', inputFg: '#ffffff',
  inputFocus: '#6366f1', placeholder: '#6b7280', track: '#ffffff26', thumb: '#f9fafb',
  success: '#4ade80', warning: '#fbbf24', danger: '#f87171', info: '#60a5fa',
  elevationLow: '0 1 2 #00000059', elevationHigh: '0 4 12 #00000080',
};

const V = {
  ...L,
  bg: dv('color.background'), surface: dv('color.surface'),
  textPrimary: dv('color.text.primary'), textSecondary: dv('color.text.secondary'),
  border: dv('color.border'), controlBg: dv('control.background'),
  controlBgHover: dv('control.background-hover'), controlBorder: dv('control.border'),
  controlFg: dv('control.foreground'), primary: dv('color.primary'), secondary: dv('color.secondary'),
  accent: dv('color.accent'), inputBg: dv('input.background'), inputBorder: dv('input.border'),
  inputFg: dv('input.foreground'), inputFocus: dv('input.focus'), placeholder: dv('input.placeholder'),
  track: dv('progress.track'), thumb: dv('control.thumb'),
  success: dv('color.success'), warning: dv('color.warning'), danger: dv('color.danger'), info: dv('color.info'),
  radius: dv('control.radius'), borderWidth: dv('control.border.width'),
  padX: dv('control.padding.horizontal'), padY: dv('control.padding.vertical'),
};

const THEMES = [
  ['Light', V],
  ['Dark', { ...D, radius: '6', borderWidth: '1', padX: '12', padY: '6' }],
];

const textColor = (t) => t.textPrimary;
const subColor = (t) => t.textSecondary;

function comp(name, props, kids = '') {
  return `<Component name="${name}" ${props}>${kids}</Component>`;
}
function frame(name, props, kids = '') {
  return `<Frame name="${name}" ${props}>${kids}</Frame>`;
}
function txt(content, props) {
  return `<Text ${props}>${content}</Text>`;
}
function section(label, body) {
  return frame(label, 'flex="col" gap={16} w="fill"', `${txt(label, 'size={12} weight={600} textCase="uppercase" letterSpacing={0.56} color="#6b7280"')}${body}`);
}
function sectionT(label, t, body) {
  return frame(label, 'flex="col" gap={16} w="fill"', `${txt(label, `size={12} weight={600} textCase="uppercase" letterSpacing={0.56} color={${subColor(t)}}`)}${body}`);
}

// ── Component sets ───────────────────────────────────────────────────────────
function buttonSet() {
  const states = ['Default', 'Hover', 'Focus', 'Disabled', 'WithIcon'];
  const variants = [];
  for (const [theme, t] of THEMES) {
    for (const state of states) {
      const bg = state === 'Hover' ? t.controlBgHover : t.controlBg;
      const focus = state === 'Focus'
        ? `strokes={[{color:${t.controlBorder},weight:1,align:'inside'},{color:${t.accent},weight:2,align:'outside'}]}`
        : `stroke={${t.controlBorder}} strokeWidth={${t.borderWidth}} strokeAlign="inside"`;
      const op = state === 'Disabled' ? 'opacity={0.5}' : '';
      const label = state === 'Disabled' ? 'Disabled' : state === 'WithIcon' ? 'With icon' : 'Primary action';
      const icon = state === 'WithIcon' ? `<Icon name="lucide:plus" size={16} color={${t.controlFg}} />` : '';
      variants.push(comp(
        `Theme=${theme}, State=${state}`,
        `flex="row" items="center" justify="center" gap={8} h={36} px={${t.padX}} bg={${bg}} rounded={${t.radius}} ${focus} shadow="${t.elevationLow}" ${op}`,
        `${icon}${txt(label, `size={14} weight={600} lineHeight={20} color={${t.controlFg}}`)}`,
      ));
    }
  }
  return `<ComponentSet name="Button">${variants.join('')}</ComponentSet>`;
}

function textFieldSet() {
  const states = [
    ['Default', 'Ada Lovelace', 'placeholder', 1],
    ['Focused', 'Focused value', 'foreground', 2],
    ['Disabled', 'Ada Lovelace', 'placeholder', 1],
  ];
  const variants = [];
  for (const [theme, t] of THEMES) {
    for (const [state, value, colorKey, width] of states) {
      const color = colorKey === 'foreground' ? t.inputFg : t.placeholder;
      const stroke = width === 2 ? t.inputFocus : t.inputBorder;
      const op = state === 'Disabled' ? 'opacity={0.5}' : '';
      variants.push(comp(
        `Theme=${theme}, State=${state}`,
        `flex="col" gap={6} w={280} ${op}`,
        `${txt('Name', `size={16} lineHeight={24} color={${t.textPrimary}}`)}` +
        frame('Input', `h={36} w="fill" flex="row" items="center" px={${t.padX}} bg={${t.inputBg}} rounded={${t.radius}} stroke={${stroke}} strokeWidth={${width}} strokeAlign="inside"`,
          txt(value, `size={16} color={${color}}`)),
      ));
    }
  }
  return `<ComponentSet name="TextField">${variants.join('')}</ComponentSet>`;
}

function fieldOnlySet(name, inner) {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}`, `flex="row" items="center" gap={8} h={36} px={${t.padX}} w={280} bg={${t.inputBg}} rounded={${t.radius}} stroke={${t.inputBorder}} strokeWidth={${t.borderWidth}} strokeAlign="inside"`, inner(t)));
  }
  return `<ComponentSet name="${name}">${variants.join('')}</ComponentSet>`;
}

function selectSet() {
  return fieldOnlySet('Select', (t) =>
    `<Frame name="Value" flex="row" items="center" grow={1}><Text size={16} color={${t.inputFg}}>First option</Text></Frame><Icon name="lucide:chevron-down" size={16} color={${t.textSecondary}} />`);
}
function dateSet() {
  return fieldOnlySet('Date', (t) =>
    `<Icon name="lucide:calendar" size={16} color={${t.textSecondary}} /><Text size={16} color={${t.inputFg}}>2026-11-10</Text>`);
}
function colorSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}`, `flex="row" items="center" h={36} w={72} p={6} bg={${t.inputBg}} rounded={${t.radius}} stroke={${t.inputBorder}} strokeWidth={${t.borderWidth}} strokeAlign="inside"`,
      frame('Swatch', `w="fill" h="fill" rounded={4} bg={${t.primary}}`)));
  }
  return `<ComponentSet name="Color">${variants.join('')}</ComponentSet>`;
}

function switchSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    const off = comp(`Theme=${theme}, State=Off`, `w={44} h={24} bg={${dvOr(t, 'toggle.track.off')}} rounded={9999}`,
      frame('Thumb', `x={2} y={2} w={20} h={20} bg={${t.thumb}} rounded={9999}`));
    const on = comp(`Theme=${theme}, State=On`, `w={44} h={24} bg={${dvOr(t, 'toggle.track.on')}} rounded={9999}`,
      frame('Thumb', `x={22} y={2} w={20} h={20} bg={${t.thumb}} rounded={9999}`));
    const focus = comp(`Theme=${theme}, State=Focus`, `w={44} h={24} bg={${dvOr(t, 'toggle.track.off')}} rounded={9999} strokes={[{color:${t.accent},weight:2,align:'outside'}]}`,
      frame('Thumb', `x={2} y={2} w={20} h={20} bg={${t.thumb}} rounded={9999}`));
    variants.push(off, on, focus);
  }
  return `<ComponentSet name="Switch">${variants.join('')}</ComponentSet>`;
}

function dvOr(t, name) {
  return t === V ? dv(name) : (name === 'toggle.track.off' ? D.controlBorder : D.accent);
}

function checkboxSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}, State=Unchecked`, `w={16} h={16} bg={${t.inputBg}} rounded={3} stroke={${t.controlBorder}} strokeWidth={1} strokeAlign="inside"`));
    variants.push(comp(`Theme=${theme}, State=Checked`, `w={16} h={16} flex="row" items="center" justify="center" bg={${t.accent}} rounded={3}`,
      `<Icon name="lucide:check" size={12} color="#ffffff" />`));
  }
  return `<ComponentSet name="Checkbox">${variants.join('')}</ComponentSet>`;
}

function sliderSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    const thumbFocus = `strokes={[{color:${t.thumb},weight:1,align:'inside'},{color:${t.accent},weight:2,align:'outside'}]}`;
    for (const state of ['Default', 'Focus']) {
      const thumb = frame('Thumb', `x={88} y={-5} w={16} h={16} bg={${t.thumb}} rounded={9999} ${state === 'Focus' ? thumbFocus : `stroke={${t.track}} strokeWidth={1} strokeAlign="inside"`}`);
      variants.push(comp(
        `Theme=${theme}, State=${state}`,
        'flex="row" items="center" gap={10} h={20}',
        frame('Track', `w={240} h={6} rounded={9999} bg={${t.track}}`,
          frame('Fill', `x={0} y={0} w={96} h={6} rounded={9999} bg={${t.accent}}`) + thumb) +
        txt('40', `size={16} color={${t.textPrimary}}`),
      ));
    }
  }
  return `<ComponentSet name="Slider">${variants.join('')}</ComponentSet>`;
}

function barSet(name, height, fillW) {
  const variants = [];
  for (const [theme, t] of THEMES) {
    const track = name === 'Gauge' ? dvOr(t, 'gauge.track') : dvOr(t, 'progress.track');
    const fill = name === 'Gauge' ? dvOr(t, 'gauge.fill') : dvOr(t, 'progress.fill');
    variants.push(comp(`Theme=${theme}`, `w={320} h={${height}} rounded={9999} bg={${track}}`,
      frame('Fill', `x={0} y={0} w={${fillW}} h={${height}} rounded={9999} bg={${fill}}`)));
  }
  return `<ComponentSet name="${name}">${variants.join('')}</ComponentSet>`;
}

function spinnerSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}`, 'w={20} h={20}',
      `<Ellipse x={0} y={0} w={20} h={20} stroke={${t.track}} strokeWidth={3} strokeAlign="inside" /><Icon x={0} y={0} name="lucide:loader-circle" size={20} color={${t.accent}} />`));
  }
  return `<ComponentSet name="Spinner">${variants.join('')}</ComponentSet>`;
}

function stepperSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    const btn = (icon) => frame('Button', `w={28} h={28} flex="row" items="center" justify="center" rounded={6} bg={${t.surface}} stroke={${t.border}} strokeWidth={1} strokeAlign="inside"`,
      `<Icon name="lucide:${icon}" size={14} color={${t.accent}} />`);
    variants.push(comp(`Theme=${theme}`, 'flex="row" items="center" gap={8}',
      `${btn('minus')}${txt('3', `size={16} color={${t.textPrimary}}`)}${btn('plus')}`));
  }
  return `<ComponentSet name="Stepper">${variants.join('')}</ComponentSet>`;
}

function menuSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    const trigger = frame('Trigger', `flex="row" items="center" justify="center" h={36} px={${t.padX}} bg={${t.controlBg}} rounded={${t.radius}} stroke={${t.controlBorder}} strokeWidth={${t.borderWidth}} strokeAlign="inside" shadow="${t.elevationLow}"`,
      txt('Open menu', `size={14} weight={600} lineHeight={20} color={${t.controlFg}}`));
    variants.push(comp(`Theme=${theme}, State=Closed`, 'flex="col" gap={6} w="hug"', trigger));
    variants.push(comp(`Theme=${theme}, State=Open`, 'flex="col" gap={6} w="hug"',
      trigger + frame('Popover', `w={176} flex="col" gap={0} p={4} bg={${t.surface}} rounded={6} stroke={${t.border}} strokeWidth={1} strokeAlign="inside" shadow="${t.elevationHigh}"`,
        frame('Item', `h={36} flex="row" items="center" px={12}`, txt('First item', `size={16} color={${t.textPrimary}}`)) +
        frame('Item', `h={36} flex="row" items="center" px={12}`, txt('Second item', `size={16} color={${t.textPrimary}}`))))); 
  }
  return `<ComponentSet name="Menu">${variants.join('')}</ComponentSet>`;
}

function mediaSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}`, `w={384} h={216} flex="row" items="center" justify="center" bg={${t.surface}} rounded={6}`,
      frame('Play', `w={56} h={56} flex="row" items="center" justify="center" rounded={9999} bg={${t.controlBg}} stroke={${t.controlBorder}} strokeWidth={1} strokeAlign="inside"`,
        `<Icon name="lucide:play" size={24} color={${t.primary}} />`)));
  }
  return `<ComponentSet name="Media">${variants.join('')}</ComponentSet>`;
}

function iconSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}`, 'w={24} h={24} flex="row" items="center" justify="center"',
      `<Icon name="lucide:plus" size={24} color={${t.textPrimary}} />`));
  }
  return `<ComponentSet name="Icon">${variants.join('')}</ComponentSet>`;
}

function labelSet() {
  const variants = [];
  for (const [theme, t] of THEMES) {
    variants.push(comp(`Theme=${theme}`, 'flex="row" items="center"',
      txt('Label', `size={16} lineHeight={24} color={${t.textPrimary}}`)));
  }
  return `<ComponentSet name="Label">${variants.join('')}</ComponentSet>`;
}

// ── Foundations ──────────────────────────────────────────────────────────────
const COLORS = [
  ['color.background', 'Background', L.bg, D.bg],
  ['color.surface', 'Surface', L.surface, D.surface],
  ['color.text.primary', 'Text primary', L.textPrimary, D.textPrimary],
  ['color.text.secondary', 'Text secondary', L.textSecondary, D.textSecondary],
  ['color.primary', 'Primary', L.primary, D.primary],
  ['color.secondary', 'Secondary', L.secondary, D.secondary],
  ['color.accent', 'Accent', L.accent, D.accent],
  ['color.border', 'Border', L.border, D.border],
  ['color.separator', 'Separator', L.separator, D.separator],
  ['color.success', 'Success', L.success, D.success],
  ['color.warning', 'Warning', L.warning, D.warning],
  ['color.danger', 'Danger', L.danger, D.danger],
  ['color.info', 'Info', L.info, D.info],
  ['control.background', 'Control background', L.controlBg, D.controlBg],
  ['control.border', 'Control border', L.controlBorder, D.controlBorder],
  ['control.foreground', 'Control foreground', L.controlFg, D.controlFg],
  ['input.focus', 'Input focus', L.inputFocus, D.inputFocus],
  ['input.placeholder', 'Placeholder', L.placeholder, D.placeholder],
];

const BASE_SWATCHES = [
  ['gray.50', '#f9fafb'], ['gray.200', '#e5e7eb'], ['gray.300', '#d1d5db'], ['gray.400', '#9ca3af'],
  ['gray.500', '#6b7280'], ['gray.700', '#374151'], ['gray.800', '#111827'], ['gray.900', '#0f172a'],
  ['blue.400', '#60a5fa'], ['blue.600', '#2563eb'], ['indigo.400', '#818cf8'], ['indigo.500', '#6366f1'],
  ['indigo.600', '#4f46e5'], ['green.400', '#4ade80'], ['green.600', '#16a34a'], ['amber.400', '#fbbf24'],
  ['amber.600', '#d97706'], ['red.400', '#f87171'], ['red.600', '#dc2626'], ['white', '#ffffff'],
];

function swatchRow(name, hex, value, t, useVar) {
  const fill = useVar ? `{${dv(name)}}` : `"${hex}"`;
  return frame(`Row ${name}`, 'flex="row" items="center" gap={12} h={44}',
    frame('Swatch', `w={40} h={40} rounded={8} bg=${fill} stroke="#00000014" strokeWidth={1} strokeAlign="inside"`) +
    frame('Meta', 'flex="col" gap={2}',
      txt(name, `size={13} weight={500} color={${subColor(t)}}`) +
      txt(value, `size={12} color={${subColor(t)}}`)));
}

function colorPanel(mode) {
  const t = mode === 'light' ? L : D;
  const rows = COLORS.map(([name, label, lhex, dhex]) =>
    swatchRow(name, mode === 'light' ? lhex : dhex, mode === 'light' ? lhex : dhex, t, mode === 'light')).join('');
  return frame(`${mode} palette`, `flex="col" gap={8} p={24} w={520} bg="${t.bg}" rounded={12} stroke="${t.border}" strokeWidth={1} strokeAlign="inside"`,
    txt(mode === 'light' ? 'Light theme' : 'Dark theme', `size={12} weight={600} textCase="uppercase" letterSpacing={0.56} color={${subColor(t)}}`) + rows);
}

function typeRow(name, meta, sample, props, t) {
  return frame(`Type ${name}`, 'flex="row" items="center" gap={24} w="fill"',
    frame('Meta', 'flex="col" gap={2} w={200}',
      txt(name, `size={13} weight={500} color={${subColor(t)}}`) + txt(meta, `size={12} color={${subColor(t)}}`)) +
    txt(sample, `${props} color={${textColor(t)}}`));
}

function foundations() {
  const spacing = [4, 8, 12, 16, 20, 24, 28, 32, 40, 44, 52];
  const radii = [2, 6, 8, 12, 16, 9999];
  const colorBlock = frame('Color tokens', 'flex="row" gap={24} items="start" w="fill"', colorPanel('light') + colorPanel('dark'));
  const typeBlock = frame('Typography', 'flex="col" gap={18} w="fill"',
    typeRow('Heading', '20 / 600 · line-height 28', 'Pathland base design', 'size={20} weight={600} lineHeight={28}', L) +
    typeRow('Body', '16 / 400 · line-height 24', 'The quick brown fox jumps over the lazy dog.', 'size={16} lineHeight={24}', L) +
    typeRow('Label', '16 / 400 · line-height 24', 'Name', 'size={16} lineHeight={24}', L) +
    typeRow('Control / Button', '14 / 600 · line-height 20', 'Primary action', 'size={14} weight={600} lineHeight={20}', L) +
    typeRow('Caption', '12 / 400 · line-height 16', '0.875rem · 600 · 1.25rem', 'size={12} lineHeight={16}', L));
  const spacingBlock = frame('Spacing', 'flex="row" gap={20} items="end" wrap="wrap" w="fill"',
    spacing.map((v) => frame(`space-${v}`, 'flex="col" gap={6} items="start"',
      frame('Bar', `w={${v}} h={12} rounded={2} bg={${L.primary}}`) +
      txt(`${v}px`, 'size={12} color="#6b7280"'))).join(''));
  const radiusBlock = frame('Radius', 'flex="row" gap={24} items="end" w="fill"',
    radii.map((r) => frame(`radius-${r}`, 'flex="col" gap={6} items="center"',
      frame('Box', `w={64} h={64} rounded={${r}} bg="#f9fafb" stroke="#d1d5db" strokeWidth={1} strokeAlign="inside"`) +
      txt(r === 9999 ? 'full' : `${r}px`, 'size={12} color="#6b7280"'))).join(''));
  const borderBlock = frame('Borders & elevation', 'flex="row" gap={32} items="center" w="fill"',
    frame('Border widths', 'flex="row" gap={24} items="center"',
      [1, 2].map((w) => frame(`border-${w}`, 'flex="col" gap={6} items="center"',
        frame('Box', `w={64} h={64} rounded={8} bg="#ffffff" stroke="#2563eb" strokeWidth={${w}} strokeAlign="inside"`) +
        txt(`${w}px`, 'size={12} color="#6b7280"'))).join('')) +
    frame('Elevation', 'flex="row" gap={24} items="center"',
      [['Low', L.elevationLow], ['High', L.elevationHigh]].map(([n, s]) => frame(`elevation-${n}`, 'flex="col" gap={6} items="center"',
        frame('Card', `w={160} h={72} rounded={12} bg="#ffffff" shadow="${s}"`) +
        txt(n, 'size={12} color="#6b7280"'))).join('')));
  const baseBlock = frame('Base palette', 'flex="row" gap={16} wrap="wrap" w="fill"',
    BASE_SWATCHES.map(([n, hex]) => frame(`base ${n}`, 'flex="col" gap={6} w={132}',
      frame('Chip', `w="fill" h={48} rounded={8} bg="${hex}" stroke="#00000014" strokeWidth={1} strokeAlign="inside"`) +
      txt(`base.color.${n}`, 'size={11} color="#6b7280"'))).join(''));

  return frame('Foundations', 'x={0} y={0} w={1120} flex="col" gap={40} p={48} bg="#ffffff"',
    frame('Header', 'flex="col" gap={6} w="fill"',
      txt('Pathland base design', 'size={28} weight={600} lineHeight={36} color="#111827"') +
      txt('Reverse-engineered from the Style Dictionary tokens (design/tokens) and hand-authored HTML component CSS (design/html). Inter stands in for the system-ui stack.', 'size={14} lineHeight={22} color="#6b7280"')) +
    colorBlock + typeBlock + spacingBlock + radiusBlock + borderBlock + baseBlock);
}

function componentsPage() {
  const body = [
    section('Button', buttonSet()),
    section('Text fields', textFieldSet() + `<Frame name="Field row" flex="row" gap={16} wrap="wrap" items="start">${selectSet()}${dateSet()}${colorSet()}</Frame>`),
    section('Toggles', `<Frame name="Toggle row" flex="row" gap={24} wrap="wrap" items="center">${switchSet()}${checkboxSet()}</Frame>`),
    section('Slider', sliderSet()),
    section('Progress, gauge & spinner', `<Frame name="Bars" flex="col" gap={16}" items="start">${barSet('Progress', 10, 192)}${barSet('Gauge', 10, 208)}${spinnerSet()}</Frame>`),
    section('Stepper', stepperSet()),
    section('Menu', menuSet()),
    section('Media', mediaSet()),
    section('Icon & label', `<Frame name="Icons" flex="row" gap={24} items="center">${iconSet()}${labelSet()}</Frame>`),
  ].join('');
  return frame('Component library', 'x={0} y={0} w={1200} flex="col" gap={40} p={48} bg="#ffffff"',
    frame('Header', 'flex="col" gap={6} w="fill"',
      txt('Component library', 'size={28} weight={600} lineHeight={36} color="#111827"') +
      txt('Every component is a component set with Theme=Light and Theme=Dark variants. Light variants bind to the Pathland Tokens variables.', 'size={14} lineHeight={22} color="#6b7280"')) +
    body);
}

// ── Showcase ─────────────────────────────────────────────────────────────────
function inst(name, theme, state) {
  const stateProp = state ? ` State="${state}"` : '';
  return `<Instance of="${name}" Theme="${theme}"${stateProp} />`;
}

function showcaseBoard(theme, t, x, pageY = 0) {
  const board = (label, body) => sectionT(label, t, body);
  const buttonRow = frame('Buttons', 'flex="row" gap={12} wrap="wrap" items="center"',
    inst('Button', theme, 'Default') + inst('Button', theme, 'Disabled') + inst('Button', theme, 'WithIcon'));
  const fields = frame('Fields', 'flex="col" gap={8} w={384}',
    inst('TextField', theme, 'Default') + inst('TextField', theme, 'Focused') +
    inst('Select', theme) +
    frame('Date & color', 'flex="row" gap={12} items="center" wrap="wrap"', inst('Date', theme) + inst('Color', theme)));
  const toggle = (name, state, label) => frame(`Toggle ${label}`, 'flex="row" gap={8} items="center"',
    inst(name, theme, state) + txt(label, `size={16} lineHeight={24} color={${textColor(t)}}`));
  const toggles = frame('Toggles', 'flex="row" gap={24} wrap="wrap" items="center"',
    toggle('Switch', 'On', 'Switch on') + toggle('Switch', 'Off', 'Switch off') +
    toggle('Checkbox', 'Checked', 'Checkbox') + toggle('Checkbox', 'Unchecked', 'Unchecked'));
  const bars = frame('Bars', 'flex="col" gap={10} w={320} items="start"',
    inst('Progress', theme) + inst('Gauge', theme) +
    frame('Loading', 'flex="row" gap={10} items="center"', inst('Spinner', theme) + txt('Loading…', `size={16} lineHeight={24} color={${textColor(t)}}`)));
  return frame(`Showcase ${theme}`, `x={${x}} y={${pageY}} w={896} flex="col" gap={32} p={32} bg={${t.bg}} rounded={12} stroke={${t.border}} strokeWidth={1} strokeAlign="inside"`,
    frame('Header', 'flex="row" items="center" justify="between" w="fill"',
      txt('Pathland base design', `size={20} weight={600} lineHeight={28} color={${textColor(t)}}`) +
      txt(`${theme} theme`, `size={12} weight={600} textCase="uppercase" letterSpacing={0.56} color={${subColor(t)}}`)) +
    board('Buttons', buttonRow) +
    board('Fields', fields) +
    board('Toggles', toggles) +
