  const buttonRow = frame('Buttons', 'flex="row" gap={12} wrap="wrap" items="center"',
    inst('Button', theme, 'Default') + inst('Button', theme, 'Disabled') + inst('Button', theme, 'WithIcon'));
  const fields = frame('Fields', 'flex="col" gap={8} w={384}',
    inst('TextField', theme, 'Default') + inst('TextField', theme, 'Focused') +
    inst('Select', theme) +
    frame('Date & color', 'flex="row" gap={12} items="center" wrap="wrap"', inst('Date', theme) + inst('Color', theme)));
  const toggle = (name, state, label) => frame(`Toggle ${label}`, 'flex="row" gap={8} items="center"',
    inst(name, theme, state) + txt(label, `size={16} lineHeight={24} color=${A(t.textPrimary)}`));
  const toggles = frame('Toggles', 'flex="row" gap={24} wrap="wrap" items="center"',
    toggle('Switch', 'On', 'Switch on') + toggle('Switch', 'Off', 'Switch off') +
    toggle('Checkbox', 'Checked', 'Checkbox') + toggle('Checkbox', 'Unchecked', 'Unchecked'));
  const bars = frame('Bars', 'flex="col" gap={10} w={320} items="start"',
    inst('Progress', theme) + inst('Gauge', theme) +
    frame('Loading', 'flex="row" gap={10} items="center"', inst('Spinner', theme) + txt('Loading…', `size={16} lineHeight={24} color=${A(t.textPrimary)}`)));
  return frame(`Showcase ${theme}`, `x={${x}} y={0} w={896} flex="col" gap={32} p={32} bg=${A(t.bg)} rounded={12} stroke=${A(t.border)} strokeWidth={1} strokeAlign="inside"`,
    frame('Header', 'flex="row" items="center" justify="between" w="fill"',
      txt('Pathland base design', `size={20} weight={600} lineHeight={28} color=${A(t.textPrimary)}`) +
      txt(`${theme} theme`, `size={12} weight={600} textCase="uppercase" letterSpacing={0.56} color=${A(t.textSecondary)}`)) +
    sectionT('Buttons', t, buttonRow) +
    sectionT('Fields', t, fields) +
    sectionT('Toggles', t, toggles) +
    sectionT('Slider', t, inst('Slider', theme)) +
    sectionT('Progress, gauge & spinner', t, bars) +
    sectionT('Stepper', t, inst('Stepper', theme)) +
    sectionT('Menu', t, inst('Menu', theme, 'Open')) +
    sectionT('Media', t, inst('Media', theme)));
}

function showcasePage() {
  return frame('Showcase', 'x={0} y={0} w={1920} flex="row" gap={64} p={48} bg="#f8fafc"',
    showcaseBoard('Light', L, 0) + showcaseBoard('Dark', D, 960));
}

function writeArgs(file, jsx) {
  fs.writeFileSync(path.join(OUT, file), JSON.stringify({ jsx }, null, 2));
}

writeArgs('foundations.args.json', foundations());
writeArgs('components.args.json', componentsPage());
writeArgs('showcase.args.json', showcasePage());
console.log('wrote page args');

