import fs from 'node:fs';
import path from 'node:path';

const OUT = '/var/folders/5p/0d4szgs13t5b74h2c379j3gc0000gn/T/opencode/pathland-design';
const dv = (n) => `designVar('${n}')`;
const isVar = (v) => String(v).startsWith('designVar(');
const A = (v) => (isVar(v) ? `{${v}}` : `"${v}"`);
const R = (v) => (isVar(v) ? v : `"${v}"`);

const L = {
  bg: '#ffffff', surface: '#ffffff', textPrimary: '#111827', textSecondary: '#6b7280',
  border: '#e5e7eb', controlBg: '#ffffff', controlBgHover: '#f9fafb',
  controlBorder: '#d1d5db', controlFg: '#111827', primary: '#2563eb', secondary: '#4f46e5',
  accent: '#2563eb', inputBg: '#ffffff', inputBorder: '#d1d5db', inputFg: '#111827',
  inputFocus: '#4f46e5', placeholder: '#9ca3af', track: '#e5e7eb', thumb: '#ffffff',
  success: '#16a34a', warning: '#d97706', danger: '#dc2626', info: '#2563eb',
  elevationLow: '0 1 2 #0000000d', elevationHigh: '0 4 12 #00000026',
  radius: '6', borderWidth: '1', padX: '12', padY: '6', switchOff: '#d1d5db', switchOn: '#2563eb',
};

const D = {
  bg: '#0f172a', surface: '#111827', textPrimary: '#f9fafb', textSecondary: '#9ca3af',
  border: '#374151', controlBg: '#272e3f', controlBgHover: '#3f4555',
  controlBorder: '#333a4a', controlFg: '#f9fafb', primary: '#60a5fa', secondary: '#818cf8',
  accent: '#60a5fa', inputBg: '#1b2335', inputBorder: '#272e3f', inputFg: '#ffffff',
  inputFocus: '#6366f1', placeholder: '#6b7280', track: '#333a4a', thumb: '#f9fafb',
  success: '#4ade80', warning: '#fbbf24', danger: '#f87171', info: '#60a5fa',
  elevationLow: '0 1 2 #00000059', elevationHigh: '0 4 12 #00000080',
  radius: '6', borderWidth: '1', padX: '12', padY: '6', switchOff: '#333a4a', switchOn: '#60a5fa',
};

const V = {
  ...L,
  bg: dv('color.background'), surface: dv('color.surface'),
  textPrimary: dv('color.text.primary'), textSecondary: dv('color.text.secondary'),
  border: dv('color.border'), controlBg: dv('control.background'),
  controlBgHover: dv('control.background.hover'), controlBorder: dv('control.border'),
  controlFg: dv('control.foreground'), primary: dv('color.primary'), secondary: dv('color.secondary'),
  accent: dv('color.accent'), inputBg: dv('input.background'), inputBorder: dv('input.border'),
  inputFg: dv('input.foreground'), inputFocus: dv('input.focus'), placeholder: dv('input.placeholder'),
  track: dv('progress.track'), thumb: dv('control.thumb'),
  success: dv('color.success'), warning: dv('color.warning'), danger: dv('color.danger'), info: dv('color.info'),
  radius: dv('control.radius'), borderWidth: dv('control.border.width'),
  padX: dv('control.padding.horizontal'), padY: dv('control.padding.vertical'),
  switchOff: dv('toggle.track.off'), switchOn: dv('toggle.track.on'),
};

const THEMES = [['Light', V], ['Dark', D]];
const suffix = (theme) => (theme === 'Dark' ? ' Dark' : '');
const compName = (name, theme) => `${name}${suffix(theme)}`;

function comp(name, props, kids = '') { return `<Component name="${name}" ${props}>${kids}</Component>`; }
function frame(name, props, kids = '') { return `<Frame name="${name}" ${props}>${kids}</Frame>`; }
function txt(content, props) { return `<Text ${props}>${content}</Text>`; }

// ── component variant builders (per theme) ───────────────────────────────────
function buttonVariants(theme, t) {
  const out = [];
  for (const state of ['Default', 'Hover', 'Focus', 'Disabled', 'WithIcon']) {
    const bg = state === 'Hover' ? t.controlBgHover : t.controlBg;
    const focus = state === 'Focus'
      ? `strokes={[{color:${R(t.controlBorder)},weight:1,align:'inside'},{color:${R(t.accent)},weight:2,align:'outside'}]}`
      : `stroke=${A(t.controlBorder)} strokeWidth={${t.borderWidth}} strokeAlign="inside"`;
    const op = state === 'Disabled' ? 'opacity={0.5}' : '';
    const label = state === 'Disabled' ? 'Disabled' : state === 'WithIcon' ? 'With icon' : 'Primary action';
    const icon = state === 'WithIcon' ? `<Icon name="lucide:plus" size={16} color=${A(t.controlFg)} />` : '';
    out.push(comp(`State=${state}`,
      `flex="row" items="center" justify="center" gap={8} h={36} px={${t.padX}} bg=${A(bg)} rounded={${t.radius}} ${focus} shadow="${t.elevationLow}" ${op}`,
      `${icon}${txt(label, `size={14} weight={600} lineHeight={20} color=${A(t.controlFg)}`)}`));
  }
  return out;
}

function textFieldVariants(theme, t) {
  const out = [];
  const states = [
    ['Default', 'Ada Lovelace', 'placeholder', 1],
    ['Focused', 'Focused value', 'foreground', 2],
    ['Disabled', 'Ada Lovelace', 'placeholder', 1],
  ];
  for (const [state, value, colorKey, width] of states) {
    const color = colorKey === 'foreground' ? t.inputFg : t.placeholder;
    const stroke = width === 2 ? t.inputFocus : t.inputBorder;
    out.push(comp(`State=${state}`, `flex="col" gap={6} w={280} ${state === 'Disabled' ? 'opacity={0.5}' : ''}`,
      txt('Name', `size={16} lineHeight={24} color=${A(t.textPrimary)}`) +
      frame('Input', `h={36} w="fill" flex="row" items="center" px={${t.padX}} bg=${A(t.inputBg)} rounded={${t.radius}} stroke=${A(stroke)} strokeWidth={${width}} strokeAlign="inside"`,
        txt(value, `size={16} color=${A(color)}`))));
  }
  return out;
}

function selectSingle(theme, t) {
  return comp(compName('Select', theme), `flex="row" items="center" gap={8} h={36} px={${t.padX}} w={280} bg=${A(t.inputBg)} rounded={${t.radius}} stroke=${A(t.inputBorder)} strokeWidth={${t.borderWidth}} strokeAlign="inside"`,
    `<Frame name="Value" flex="row" items="center" grow={1}><Text size={16} color=${A(t.inputFg)}>First option</Text></Frame><Icon name="lucide:chevron-down" size={16} color=${A(t.textSecondary)} />`);
}
function dateSingle(theme, t) {
  return comp(compName('Date', theme), `flex="row" items="center" gap={8} h={36} px={${t.padX}} w={184} bg=${A(t.inputBg)} rounded={${t.radius}} stroke=${A(t.inputBorder)} strokeWidth={${t.borderWidth}} strokeAlign="inside"`,
    `<Icon name="lucide:calendar" size={16} color=${A(t.textSecondary)} /><Text size={16} color=${A(t.inputFg)}>2026-11-10</Text>`);
}
function colorSingle(theme, t) {
  return comp(compName('Color', theme), `flex="row" items="center" h={36} w={72} p={6} bg=${A(t.inputBg)} rounded={${t.radius}} stroke=${A(t.inputBorder)} strokeWidth={${t.borderWidth}} strokeAlign="inside"`,
    frame('Swatch', `w="fill" h="fill" rounded={4} bg=${A(t.primary)}`));
}

function switchVariants(theme, t) {
  return [
    comp('State=Off', `w={44} h={24} bg=${A(t.switchOff)} rounded={9999}`, frame('Thumb', `x={2} y={2} w={20} h={20} bg=${A(t.thumb)} rounded={9999}`)),
    comp('State=On', `w={44} h={24} bg=${A(t.switchOn)} rounded={9999}`, frame('Thumb', `x={22} y={2} w={20} h={20} bg=${A(t.thumb)} rounded={9999}`)),
    comp('State=Focus', `w={44} h={24} bg=${A(t.switchOff)} rounded={9999} strokes={[{color:${R(t.accent)},weight:2,align:'outside'}]}`, frame('Thumb', `x={2} y={2} w={20} h={20} bg=${A(t.thumb)} rounded={9999}`)),
  ];
}

function checkboxVariants(theme, t) {
  return [
    comp('State=Unchecked', `w={16} h={16} bg=${A(t.inputBg)} rounded={3} stroke=${A(t.controlBorder)} strokeWidth={1} strokeAlign="inside"`),
    comp('State=Checked', `w={16} h={16} flex="row" items="center" justify="center" bg=${A(t.accent)} rounded={3}`, `<Icon name="lucide:check" size={12} color="#ffffff" />`),
  ];
}

function sliderVariants(theme, t) {
  const out = [];
  for (const state of ['Default', 'Focus']) {
    const thumbStroke = state === 'Focus'
      ? `strokes={[{color:${R(t.thumb)},weight:1,align:'inside'},{color:${R(t.accent)},weight:2,align:'outside'}]}`
      : `stroke=${A(t.track)} strokeWidth={1} strokeAlign="inside"`;
    out.push(comp(`State=${state}`, 'flex="row" items="center" gap={10} h={20}',
      frame('Track', `w={240} h={6} rounded={9999} bg=${A(t.track)}`,
        frame('Fill', `x={0} y={0} w={96} h={6} rounded={9999} bg=${A(t.accent)}`) +
        frame('Thumb', `x={88} y={-5} w={16} h={16} bg=${A(t.thumb)} rounded={9999} ${thumbStroke}`)) +
      txt('40', `size={16} color=${A(t.textPrimary)}`)));
  }
  return out;
}

function barSingle(name, theme, t, height, fillW, trackName, fillName) {
  const track = theme === 'Light' ? dv(trackName) : t.track;
  const fill = theme === 'Light' ? dv(fillName) : t.primary;
  return comp(compName(name, theme), `w={320} h={${height}} rounded={9999} bg=${A(track)}`,
    frame('Fill', `x={0} y={0} w={${fillW}} h={${height}} rounded={9999} bg=${A(fill)}`));
}

function spinnerSingle(theme, t) {
  return comp(compName('Spinner', theme), 'w={20} h={20}',
    `<Ellipse x={0} y={0} w={20} h={20} stroke=${A(t.track)} strokeWidth={3} strokeAlign="inside" /><Icon x={0} y={0} name="lucide:loader-circle" size={20} color=${A(t.accent)} />`);
}

function stepperSingle(theme, t) {
  const btn = (icon) => frame('Button', `w={28} h={28} flex="row" items="center" justify="center" rounded={6} bg=${A(t.surface)} stroke=${A(t.border)} strokeWidth={1} strokeAlign="inside"`,
    `<Icon name="lucide:${icon}" size={14} color=${A(t.accent)} />`);
  return comp(compName('Stepper', theme), 'flex="row" items="center" gap={8}',
    `${btn('minus')}${txt('3', `size={16} color=${A(t.textPrimary)}`)}${btn('plus')}`);
}

function menuVariants(theme, t) {
  const trigger = frame('Trigger', `flex="row" items="center" justify="center" h={36} px={${t.padX}} bg=${A(t.controlBg)} rounded={${t.radius}} stroke=${A(t.controlBorder)} strokeWidth={${t.borderWidth}} strokeAlign="inside" shadow="${t.elevationLow}"`,
    txt('Open menu', `size={14} weight={600} lineHeight={20} color=${A(t.controlFg)}`));
  return [
    comp('State=Closed', 'flex="col" gap={6} w="hug"', trigger),
    comp('State=Open', 'flex="col" gap={6} w="hug"',
      trigger + frame('Popover', `w={176} flex="col" gap={0} p={4} bg=${A(t.surface)} rounded={6} stroke=${A(t.border)} strokeWidth={1} strokeAlign="inside" shadow="${t.elevationHigh}"`,
        frame('Item', 'h={36} flex="row" items="center" px={12}', txt('First item', `size={16} color=${A(t.textPrimary)}`)) +
        frame('Item', 'h={36} flex="row" items="center" px={12}', txt('Second item', `size={16} color=${A(t.textPrimary)}`)))),
  ];
}

function mediaSingle(theme, t) {
  return comp(compName('Media', theme), `w={384} h={216} flex="row" items="center" justify="center" bg=${A(t.surface)} rounded={6}`,
    frame('Play', `w={56} h={56} flex="row" items="center" justify="center" rounded={9999} bg=${A(t.controlBg)} stroke=${A(t.controlBorder)} strokeWidth={1} strokeAlign="inside"`,
      `<Icon name="lucide:play" size={24} color=${A(t.primary)} />`));
}

function iconSingle(theme, t) {
  return comp(compName('Icon', theme), 'w={24} h={24} flex="row" items="center" justify="center"',
    `<Icon name="lucide:plus" size={24} color=${A(t.textPrimary)} />`);
}

function labelSingle(theme, t) {
  return comp(compName('Label', theme), 'flex="row" items="center"',
    txt('Label', `size={16} lineHeight={24} color=${A(t.textPrimary)}`));
}

// ── themed pair presentation ─────────────────────────────────────────────────
function themePanel(theme, t, inner, width) {
  return frame(`${theme} panel`, `flex="col" gap={12} p={20} w={${width + 40}} bg=${A(t.bg)} rounded={12} stroke=${A(t.border)} strokeWidth={1} strokeAlign="inside"`,
    txt(theme, `size={11} weight={600} textCase="uppercase" letterSpacing={0.5} color=${A(t.textSecondary)}`) + inner);
}

function statePair(name, width, variantsFn) {
  const panels = THEMES.map(([theme, t]) => {
    const variants = variantsFn(theme, t);
    const set = `<ComponentSet name="${compName(name, theme)}" w={${width}} flex="row" wrap="wrap" gap={16} p={20} items="start">${variants.join('')}</ComponentSet>`;
    return themePanel(theme, t, set, width);
  });
  return frame(`${name} theme pair`, 'flex="row" wrap="wrap" gap={24} items="start" w="fill"', panels.join(''));
}

function singlePair(name, width, singleFn) {
  const panels = THEMES.map(([theme, t]) => themePanel(theme, t, singleFn(theme, t), width));
  return frame(`${name} theme pair`, 'flex="row" wrap="wrap" gap={24} items="start" w="fill"', panels.join(''));
}

// ── foundations ──────────────────────────────────────────────────────────────
const COLORS = [
  ['color.background', L.bg, D.bg], ['color.surface', L.surface, D.surface],
  ['color.text.primary', L.textPrimary, D.textPrimary], ['color.text.secondary', L.textSecondary, D.textSecondary],
  ['color.primary', L.primary, D.primary], ['color.secondary', L.secondary, D.secondary],
  ['color.accent', L.accent, D.accent], ['color.border', L.border, D.border],
  ['color.separator', L.separator, D.separator], ['color.success', L.success, D.success],
  ['color.warning', L.warning, D.warning], ['color.danger', L.danger, D.danger],
  ['color.info', L.info, D.info], ['control.background', L.controlBg, D.controlBg],
  ['control.border', L.controlBorder, D.controlBorder], ['control.foreground', L.controlFg, D.controlFg],
  ['input.focus', L.inputFocus, D.inputFocus], ['input.placeholder', L.placeholder, D.placeholder],
];
const BASE_SWATCHES = [
  ['gray.50', '#f9fafb'], ['gray.200', '#e5e7eb'], ['gray.300', '#d1d5db'], ['gray.400', '#9ca3af'],
  ['gray.500', '#6b7280'], ['gray.700', '#374151'], ['gray.800', '#111827'], ['gray.900', '#0f172a'],
  ['blue.400', '#60a5fa'], ['blue.600', '#2563eb'], ['indigo.400', '#818cf8'], ['indigo.500', '#6366f1'],
  ['indigo.600', '#4f46e5'], ['green.400', '#4ade80'], ['green.600', '#16a34a'], ['amber.400', '#fbbf24'],
  ['amber.600', '#d97706'], ['red.400', '#f87171'], ['red.600', '#dc2626'], ['white', '#ffffff'],
];

function swatchRow(name, hex, showVar, t) {
  return frame(`Row ${name}`, 'flex="row" items="center" gap={12} h={44}',
    frame('Swatch', `w={40} h={40} rounded={8} bg=${A(showVar ? dv(name) : hex)} stroke="#00000014" strokeWidth={1} strokeAlign="inside"`) +
    frame('Meta', 'flex="col" gap={2}',
      txt(name, `size={13} weight={500} color=${A(t.textSecondary)}`) +
      txt(hex, `size={12} color=${A(t.textSecondary)}`)));
}
function colorPanel(mode) {
  const t = mode === 'light' ? L : D;
  const rows = COLORS.map(([name, lhex, dhex]) => swatchRow(name, mode === 'light' ? lhex : dhex, mode === 'light', t)).join('');
  return frame(`${mode} palette`, `flex="col" gap={8} p={24} w={520} bg=${A(t.bg)} rounded={12} stroke=${A(t.border)} strokeWidth={1} strokeAlign="inside"`,
    txt(mode === 'light' ? 'Light theme' : 'Dark theme', `size={12} weight={600} textCase="uppercase" letterSpacing={0.56} color=${A(t.textSecondary)}`) + rows);
}
function typeRow(name, meta, sample, props, t) {
  return frame(`Type ${name}`, 'flex="row" items="center" gap={24} w="fill"',
    frame('Meta', 'flex="col" gap={2} w={200}',
      txt(name, `size={13} weight={500} color=${A(t.textSecondary)}`) +
      txt(meta, `size={12} color=${A(t.textSecondary)}`)) +
    txt(sample, `${props} color=${A(t.textPrimary)}`));
}
function foundations() {
  const spacing = [4, 8, 12, 16, 20, 24, 28, 32, 40, 44, 52];
  const radii = [2, 6, 8, 12, 16, 9999];
  const colorBlock = frame('Color tokens', 'flex="row" gap={24} items="start" w="fill"', colorPanel('light') + colorPanel('dark'));
  const typeBlock = frame('Typography', 'flex="col" gap={18} w="fill"',
    typeRow('Heading', '20 / 600 · line-height 28', 'Pathland base design', 'size={20} weight={600} lineHeight={28}', L) +
    typeRow('Body', '16 / 400 · line-height 24', 'The quick brown fox jumps over the lazy dog.', 'size={16} lineHeight={24}', L) +
    typeRow('Label', '16 / 400 · line-height 24', 'Name', 'size={16} lineHeight={24}', L) +
    typeRow('Control / Button', '14 / 600 · line-height 20', 'Primary action', 'size={14} weight={600} lineHeight={20}', L) +
    typeRow('Caption', '12 / 400 · line-height 16', '0.875rem · 600 · 1.25rem', 'size={12} lineHeight={16}', L));
  const spacingBlock = frame('Spacing', 'flex="row" gap={20} items="end" wrap="wrap" w="fill"',
    spacing.map((v) => frame(`space-${v}`, 'flex="col" gap={6} items="start"',
      frame('Bar', `w={${v}} h={12} rounded={2} bg=${A(L.primary)}`) +
      txt(`${v}px`, `size={12} color=${A(L.textSecondary)}`))).join(''));
  const radiusBlock = frame('Radius', 'flex="row" gap={24} items="end" w="fill"',
    radii.map((r) => frame(`radius-${r}`, 'flex="col" gap={6} items="center"',
      frame('Box', `w={64} h={64} rounded={${r}} bg="#f9fafb" stroke="#d1d5db" strokeWidth={1} strokeAlign="inside"`) +
      txt(r === 9999 ? 'full' : `${r}px`, `size={12} color=${A(L.textSecondary)}`))).join(''));
  const borderBlock = frame('Borders & elevation', 'flex="row" gap={32} items="center" w="fill"',
    frame('Border widths', 'flex="row" gap={24} items="center"',
      [1, 2].map((w) => frame(`border-${w}`, 'flex="col" gap={6} items="center"',
        frame('Box', `w={64} h={64} rounded={8} bg="#ffffff" stroke=${A(L.primary)} strokeWidth={${w}} strokeAlign="inside"`) +
        txt(`${w}px`, `size={12} color=${A(L.textSecondary)}`))).join('')) +
    frame('Elevation', 'flex="row" gap={24} items="center"',
      [['Low', L.elevationLow], ['High', L.elevationHigh]].map(([n, s]) => frame(`elevation-${n}`, 'flex="col" gap={6} items="center"',
        frame('Card', `w={160} h={72} rounded={12} bg="#ffffff" shadow="${s}"`) +
        txt(n, `size={12} color=${A(L.textSecondary)}`))).join('')));
  const baseBlock = frame('Base palette', 'flex="row" gap={16} wrap="wrap" w="fill"',
    BASE_SWATCHES.map(([n, hex]) => frame(`base ${n}`, 'flex="col" gap={6} w={132}`,
      frame('Chip', `w="fill" h={48} rounded={8} bg=${A(hex)} stroke="#00000014" strokeWidth={1} strokeAlign="inside"`) +
      txt(`base.color.${n}`, `size={11} color=${A(L.textSecondary)}`))).join(''));

  return frame('Foundations', 'x={0} y={0} w={1120} flex="col" gap={40} p={48} bg="#ffffff"',
