}

function componentsPage() {
  const body = [
    section('Button', statePair('Button', 840, buttonVariants)),
    section('Text field', statePair('TextField', 900, textFieldVariants)),
    section('Select', singlePair('Select', 300, selectSingle)),
    section('Date', singlePair('Date', 220, dateSingle)),
    section('Color', singlePair('Color', 100, colorSingle)),
    section('Switch', statePair('Switch', 360, switchVariants)),
    section('Checkbox', statePair('Checkbox', 300, checkboxVariants)),
    section('Slider', statePair('Slider', 640, sliderVariants)),
    section('Progress', singlePair('Progress', 620, (theme, t) => barSingle('Progress', theme, t, 10, 192, 'progress.track', 'progress.fill'))),
    section('Gauge', singlePair('Gauge', 620, (theme, t) => barSingle('Gauge', theme, t, 10, 208, 'gauge.track', 'gauge.fill'))),
    section('Spinner', singlePair('Spinner', 120, spinnerSingle)),
    section('Stepper', singlePair('Stepper', 320, stepperSingle)),
    section('Menu', statePair('Menu', 640, menuVariants)),
    section('Media', singlePair('Media', 900, mediaSingle)),
    section('Icon', singlePair('Icon', 140, iconSingle)),
    section('Label', singlePair('Label', 220, labelSingle)),
