  if(n.type==='FRAME' && (n.name==='Foundations'||n.name==='Component library'||n.name==='Showcase') && n.paddingTop===48){
    g.updateNode(n.id,{paddingTop:44,paddingRight:44,paddingBottom:44,paddingLeft:44}); snapped.push(n.name+' padding 48→44');
  }
  if(n.type==='FRAME' && n.name==='Showcase' && n.itemSpacing===64){ g.updateNode(n.id,{itemSpacing:52}); snapped.push('Showcase gap 64→52'); }
  if(n.type==='FRAME' && n.name==='Typography' && n.itemSpacing===18){ g.updateNode(n.id,{itemSpacing:16}); snapped.push('Typography gap 18→16'); }
}
// 2) spacing variable maps
const byName={}; for(const v of g.variables.values()) byName[v.name]=v;
const SP={2:'base.space.0_5',4:'base.space.1',6:'base.space.1_5',8:'base.space.2',10:'base.space.2_5',12:'base.space.3',14:'base.space.3_5',16:'base.space.4',20:'base.space.5',22:'base.space.5_5',24:'base.space.6',28:'base.space.7',32:'base.space.8',40:'base.space.10',44:'base.space.11',52:'base.space.13'};
const spaceVar={}; for(const k in SP){ if(byName[SP[k]]) spaceVar[k]=byName[SP[k]].id; }
const ctrlH=byName['control.padding.horizontal'].id, ctrlV=byName['control.padding.vertical'].id;
const toggleGap=byName['toggle.gap'].id, sliderGap=byName['slider.gap'].id, stepperGap=byName['stepper.gap'].id;
const ctrlSets=/^(Button|TextField|Select|Date|Menu)( Dark)?$/;
function setAncestor(n){let p=n;let d=0;while(p&&d++<20){if(p.type==='COMPONENT_SET')return p;p=p.parentId?g.getNode(p.parentId):null;}return null;}
function inInstance(n){let p=n;let d=0;while(p&&d++<25){if(p.type==='INSTANCE')return true;p=p.parentId?g.getNode(p.parentId):null;}return false;}
const fields=['itemSpacing','counterAxisSpacing','gridColumnGap','gridRowGap','paddingTop','paddingRight','paddingBottom','paddingLeft'];
let bound=0, skippedInstance=0, unmatched=0; const unmatchedVals={};
for(const n of [...g.nodes.values()]){
  if(inInstance(n)){skippedInstance++;continue;}
  const set=setAncestor(n); const setName=set?set.name:''; const isCtrl=ctrlSets.test(setName);
  for(const f of fields){
    const v=n[f];
    if(typeof v!=='number'||v===0) continue;
    if(n.boundVariables&&n.boundVariables[f]) continue;
    let vid=null;
    if(isCtrl){
      if((f==='paddingLeft'||f==='paddingRight')&&v===12) vid=ctrlH;
      if((f==='paddingTop'||f==='paddingBottom')&&v===6) vid=ctrlV;
    }
    if(!vid&&f==='itemSpacing'){
      if(/^Slider( Dark)?$/.test(setName)&&v===10) vid=sliderGap;
      else if(/^Stepper( Dark)?$/.test(setName)&&v===8) vid=stepperGap;
      else if(n.name&&n.name.startsWith('Toggle ')&&v===8) vid=toggleGap;
    }
    if(!vid) vid=spaceVar[v];
    if(vid){ g.bindVariable(n.id,f,vid); bound++; }
    else { unmatched++; unmatchedVals[v]=(unmatchedVals[v]||0)+1; }
  }
}
return {snapped, bound, skippedInstance, unmatched, unmatchedVals};
