//! CLI for the HTML golden conformance fixtures.
//!
//! `--emit`  (re)generates the committed fixtures under
//!          `lib/typescript/test/fixtures/ssr/` from the canonical Rust SSR
//!          renderer.
//! `--check` verifies the committed fixtures still match the current rendering
//!          (fails with exit code 1 on any drift — used by CI).

use pathland_render_html::HtmlRenderer;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let renderer = HtmlRenderer::new();
    match args.first().map(String::as_str) {
        Some("--emit") => match pathland_html_golden::emit(&renderer) {
            Ok(written) => {
                for p in written {
                    println!("wrote {}", p.display());
                }
            }
            Err(e) => {
                eprintln!("emit failed: {e}");
                std::process::exit(1);
            }
        },
        Some("--check") => match pathland_html_golden::check(&renderer) {
            Ok(()) => println!("golden fixtures are current"),
            Err(failures) => {
                for f in &failures {
                    eprintln!("{f}");
                }
                eprintln!("{} mismatch(es) — run `cargo run -p pathland-html-golden -- --emit`", failures.len());
                std::process::exit(1);
            }
        },
        other => {
            eprintln!("usage: pathland-html-golden --emit | --check (got {other:?})");
            std::process::exit(2);
        }
    }
}--- guard ---
//! Guard: the committed SSR golden fixtures must match the current Rust SSR
//! renderer output. Run with `cargo test -p pathland-html-golden`.
//!
//! When the renderer intentionally changes its output, regenerate the fixtures
//! with `cargo run -p pathland-html-golden -- --emit` and commit them together.

use pathland_render_html::HtmlRenderer;

#[test]
fn ssr_fixtures_are_current() {
    let renderer = HtmlRenderer::new();
    match pathland_html_golden::check(&renderer) {
        Ok(()) => {}
        Err(failures) => {
            let mut msg = String::from("SSR golden fixtures are stale:\n");
            for f in &failures {
                msg.push_str(&format!("  - {f}\n"));
            }
            msg.push_str(
                "Regenerate with `cargo run -p pathland-html-golden -- --emit` from lib/rust.",
            );
            panic!("{msg}");
        }
    }
}

