import fs from 'node:fs';
import path from 'node:path';

const OUT = '/var/folders/5p/0d4szgs13t5b74h2c379j3gc0000gn/T/opencode/pathland-design';
const DESIGN = '/Users/michael/Development/michaelkrog/Pathland/design';

const snapshot = JSON.parse(fs.readFileSync(path.join(OUT, 'snapshot-before.json'), 'utf8'));
const manifest = JSON.parse(fs.readFileSync(path.join(DESIGN, 'build/manifest.json'), 'utf8'));
const layerByPath = new Map(manifest.map((t) => [t.path, t.layer]));

function loadLayer(folder) {
  const dir = path.join(DESIGN, 'tokens', folder);
  const out = {};
  for (const file of fs.readdirSync(dir).filter((f) => f.endsWith('.json'))) {
    Object.assign(out, JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')));
  }
  return out;
}
const baseTokens = loadLayer('base');
const semanticTokens = loadLayer('semantic');
const componentTokens = loadLayer('component');
const refByPath = new Map();
for (const [tokens, layer] of [[baseTokens, 'base'], [semanticTokens, 'semantic'], [componentTokens, 'component']]) {
  for (const [p, entry] of Object.entries(tokens)) {
    const raw = entry.$value;
    const valueRef = typeof raw === 'string' ? raw.match(/^\{([^}]+)\}$/)?.[1] ?? null : null;
    const darkRaw = entry.$extensions?.pathland?.dark;
    const darkRef = typeof darkRaw === 'string' ? darkRaw.match(/^\{([^}]+)\}$/)?.[1] ?? null : null;
    refByPath.set(p, { layer, type: entry.$type, valueRef, darkRef });
  }
}

const oldCollections = new Map(snapshot.collections.map((c) => [c.id, c]));
const oldVars = snapshot.variables;
const oldNameById = new Map(oldVars.map((v) => [v.id, v.name]));

function layerFor(name) {
  if (name.startsWith('base.')) return 'base';
  const layer = layerByPath.get(name);
  if (!layer) throw new Error('no layer for ' + name);
  return layer;
}

const newVariables = [];
for (const v of oldVars) {
  const layer = layerFor(v.name);
  const col = oldCollections.get(v.collectionId);
  if (!col) throw new Error('missing collection for ' + v.name);
  const modeByName = new Map(col.modes.map((m) => [m.name, m.modeId]));
  let light;
  let dark;
  if (layer === 'base') {
    light = v.valuesByMode[modeByName.get('Value')];
    dark = light;
  } else {
    light = v.valuesByMode[modeByName.get('Light')];
    dark = v.valuesByMode[modeByName.get('Dark')];
  }
  if (light === undefined || dark === undefined) throw new Error('missing mode value for ' + v.name);
  const ref = refByPath.get(v.name);
  let description = v.description || `${layer} token`;
  if (ref?.valueRef) description += `; value ref {${ref.valueRef}}`;
  if (ref?.darkRef) description += `; dark ref {${ref.darkRef}}`;
  newVariables.push({ name: v.name, type: v.type, layer, light, dark, description });
}

// ── new tokens ──────────────────────────────────────────────────────────────
const base = [];
function addBase(name, type, value, ref) {
  base.push({ name, type, layer: 'base', light: value, dark: value, description: `base token (internal)${ref ? `; value ref {${ref}}` : ''}` });
}
addBase('base.font.size.12', 'FLOAT', 12);
addBase('base.font.size.13', 'FLOAT', 13);
addBase('base.font.size.20', 'FLOAT', 20);
addBase('base.font.size.28', 'FLOAT', 28);
addBase('base.font.weight.500', 'FLOAT', 500);
for (const lh of [16, 18, 20, 22, 24, 28, 36]) addBase(`base.font.line-height.${lh}`, 'FLOAT', lh);
addBase('base.font.letter-spacing.0', 'FLOAT', 0);
addBase('base.font.letter-spacing.0_5', 'FLOAT', 0.5);
addBase('base.font.letter-spacing.0_56', 'FLOAT', 0.56);
addBase('base.font.family.inter', 'STRING', 'Inter');
addBase('base.radius.3', 'FLOAT', 3);
addBase('base.radius.4', 'FLOAT', 4);
addBase('base.radius.2xl', 'FLOAT', 16);

const semantic = [];
function addSemantic(name, type, value, ref) {
  semantic.push({ name, type, layer: 'semantic', light: value, dark: value, description: `semantic token${ref ? `; value ref {${ref}}` : ''}` });
}
addSemantic('font.body.lineHeight', 'FLOAT', 24, 'base.font.line-height.24');
addSemantic('font.caption.size', 'FLOAT', 12, 'base.font.size.12');
addSemantic('font.caption.weight', 'FLOAT', 400, 'base.font.weight.400');
addSemantic('font.caption.lineHeight', 'FLOAT', 16, 'base.font.line-height.16');
addSemantic('font.meta.size', 'FLOAT', 13, 'base.font.size.13');
addSemantic('font.meta.weight', 'FLOAT', 500, 'base.font.weight.500');
addSemantic('font.meta.lineHeight', 'FLOAT', 20, 'base.font.line-height.20');
addSemantic('font.heading.1.size', 'FLOAT', 28, 'base.font.size.28');
addSemantic('font.heading.1.weight', 'FLOAT', 600, 'base.font.weight.600');
addSemantic('font.heading.1.lineHeight', 'FLOAT', 36, 'base.font.line-height.36');
addSemantic('font.heading.1.family', 'STRING', 'Inter', 'base.font.family.inter');
addSemantic('font.heading.2.size', 'FLOAT', 20, 'base.font.size.20');
addSemantic('font.heading.2.weight', 'FLOAT', 600, 'base.font.weight.600');
addSemantic('font.heading.2.lineHeight', 'FLOAT', 28, 'base.font.line-height.28');
addSemantic('font.heading.2.family', 'STRING', 'Inter', 'base.font.family.inter');

const component = [];
function addComponent(name, type, value, ref) {
  component.push({ name, type, layer: 'component', light: value, dark: value, description: `component token${ref ? `; value ref {${ref}}` : ''}` });
}
addComponent('toggle.checkbox.radius', 'FLOAT', 3, 'base.radius.3');
addComponent('color.swatch.radius', 'FLOAT', 4, 'base.radius.4');

const allNew = [...newVariables, ...base, ...semantic, ...component];
const names = new Set(allNew.map((v) => v.name));
if (names.size !== allNew.length) throw new Error('duplicate variable names');

const data = {
  oldCollectionNames: ['Pathland Tokens', 'Base Palette'],
  oldVars: oldVars.map((v) => ({ id: v.id, name: v.name })),
  newVariables: allNew,
  boundNodes: snapshot.boundNodes,
};

const js = `const DATA = ${JSON.stringify(data)};
const g = figma.graph;
const oldNameById = new Map(DATA.oldVars.map((v) => [v.id, v.name]));

function removeExisting(name) {
  for (const c of [...g.variableCollections.values()]) if (c.name === name) g.removeCollection(c.id);
}
function makeCollection(name, modeNames) {
  removeExisting(name);
  const c = g.createCollection(name);
  const ids = [c.modes[0].modeId];
  g.renameMode(c.id, ids[0], modeNames[0]);
  for (let i = 1; i < modeNames.length; i++) ids.push(g.createMode(c.id, modeNames[i]));
  return { id: c.id, modes: ids };
}
const baseCol = makeCollection('Base', ['Value']);
const semCol = makeCollection('Semantic', ['Light', 'Dark']);
const compCol = makeCollection('Component', ['Light', 'Dark']);
const collections = { base: baseCol, semantic: semCol, component: compCol };

const nameToNew = new Map();
const counts = { base: 0, semantic: 0, component: 0 };
for (const t of DATA.newVariables) {
  const col = collections[t.layer];
  const v = g.createVariable(t.name, t.type, col.id, t.light);
  if (t.layer !== 'base') v.valuesByMode[col.modes[1]] = t.dark;
  v.description = t.description;
  nameToNew.set(t.name, v.id);
  counts[t.layer]++;
}

let rebound = 0;
const rebindFailures = [];
for (const n of DATA.boundNodes) {
  for (const [field, oldId] of Object.entries(n.bindings)) {
    const name = oldNameById.get(oldId);
    const newId = name ? nameToNew.get(name) : null;
    if (!newId) { rebindFailures.push({ node: n.id, field, oldId, name }); continue; }
    try { g.bindVariable(n.id, field, newId); rebound++; }
    catch (e) { rebindFailures.push({ node: n.id, field, name, error: String(e) }); }
  }
}

// remove old collections after rebinding
for (const name of DATA.oldCollectionNames) removeExisting(name);

// verify no binding points at a non-existent variable
let stale = 0;
for (const n of g.nodes.values()) {
  const b = n.boundVariables || {};
  for (const [field, id] of Object.entries(b)) if (!g.variables.has(id)) stale++;
}

return {
  counts,
  totalNew: DATA.newVariables.length,
  rebound,
  rebindFailures: rebindFailures.slice(0, 20),
  rebindFailureCount: rebindFailures.length,
  stale,
  collections: [...g.variableCollections.values()].map((c) => ({ name: c.name, modes: c.modes.map((m) => m.name), vars: c.variableIds.length })),
};`;

fs.writeFileSync(path.join(OUT, 'migrate-collections.js'), js);
fs.writeFileSync(path.join(OUT, 'migration-data.json'), JSON.stringify(data, null, 2));
console.log('wrote migrate-collections.js', allNew.length, 'variables');

const g = figma.graph;
const byName = new Map();
for (const v of g.variables.values()) byName.set(v.name, v);

function valueOf(name) {
  const v = byName.get(name);
  if (!v) return undefined;
  return Object.values(v.valuesByMode)[0];
}
function isSet(n, re) { return n && re.test(n); }
function inInstance(n) {
  let p = n, d = 0;
  while (p && d++ < 25) { if (p.type === 'INSTANCE') return true; p = p.parentId ? g.getNode(p.parentId) : null; }
  return false;
}
function setAncestor(n) {
  let p = n, d = 0;
  while (p && d++ < 25) { if (p.type === 'COMPONENT_SET') return p.name; p = p.parentId ? g.getNode(p.parentId) : null; }
  return '';
}
function ancestorNamed(n, name) {
  let p = n, d = 0;
  while (p && d++ < 25) { if (p.name === name) return true; p = p.parentId ? g.getNode(p.parentId) : null; }
  return false;
}
function typeRow(n) {
  let p = n, d = 0;
  while (p && d++ < 25) { if (typeof p.name === 'string' && p.name.startsWith('Type ')) return p.name.slice(5); p = p.parentId ? g.getNode(p.parentId) : null; }
  return '';
}

function pickSize(n, set, tr) {
  const fs = n.fontSize;
  if (fs === 28) return 'font.heading.1.size';
  if (fs === 20) return 'font.heading.2.size';
  if (fs === 16) {
    if (isSet(set, /^TextField( Dark)?$/)) return ancestorNamed(n, 'Input') ? 'input.font.size' : 'label.font.size';
    if (isSet(set, /^(Select|Date|Color)( Dark)?$/)) return 'input.font.size';
    if (isSet(set, /^Menu( Dark)?$/)) return ancestorNamed(n, 'Trigger') ? 'button.font.size' : 'label.font.size';
    if (tr === 'Label') return 'label.font.size';
    return 'font.body.size';
  }
  if (fs === 14) {
    if (isSet(set, /^(Button|Menu)( Dark)?$/) || tr === 'Control / Button') return 'button.font.size';
    if (isSet(set, /^(TextField|Select|Date|Color)( Dark)?$/)) return 'control.font.size';
    return 'base.font.size.14';
  }
  if (fs === 13) return 'font.meta.size';
  if (fs === 12) return 'font.caption.size';
  return null;
}
function pickWeight(n, set, tr) {
  const fs = n.fontSize, fw = n.fontWeight;
  if (fs === 28) return 'font.heading.1.weight';
  if (fs === 20) return 'font.heading.2.weight';
  if (fw === 600) {
    if (isSet(set, /^(Button|Menu)( Dark)?$/) || tr === 'Control / Button') return 'button.font.weight';
    return 'base.font.weight.600';
  }
  if (fw === 500) return 'font.meta.weight';
  if (fw === 400) {
    if (fs === 12 && tr === 'Caption') return 'font.caption.weight';
    return 'font.body.weight';
  }
  return null;
}
function pickLineHeight(n, set, tr) {
  const fs = n.fontSize, lh = n.lineHeight;
  if (fs === 28) return 'font.heading.1.lineHeight';
  if (fs === 20) return 'font.heading.2.lineHeight';
  if (fs === 13) return 'font.meta.lineHeight';
  if (lh === 20) {
    if (isSet(set, /^(Button|Menu)( Dark)?$/) || tr === 'Control / Button') return 'button.line-height';
  }
  if (lh === 24) {
    if (isSet(set, /^(TextField|Select|Date|Color|Menu)( Dark)?$/)) return 'control.line-height';
    return 'font.body.lineHeight';
  }
  if (lh === 16) return 'font.caption.lineHeight';
  if (lh === 18) return 'base.font.line-height.18';
  if (lh === 22) return 'base.font.line-height.22';
  if (lh === 28) return 'base.font.line-height.28';
  if (lh === 36) return 'base.font.line-height.36';
  return null;
}
function pickTracking(n) {
  const ls = n.letterSpacing;
  if (ls === 0) return 'base.font.letter-spacing.0';
  if (ls === 0.5) return 'base.font.letter-spacing.0_5';
  if (ls === 0.56) return 'base.font.letter-spacing.0_56';
  return null;
}
function pickFamily(n) {
  if (n.fontSize === 28) return 'font.heading.1.family';
  if (n.fontSize === 20) return 'font.heading.2.family';
  return 'base.font.family.inter';
}

function matches(name, field, value) {
  const v = valueOf(name);
  if (v === undefined) return false;
  if (field === 'fontFamily') return v === value;
  return Math.abs(Number(v) - Number(value)) < 0.001;
}

const results = { nodes: 0, fontSize: 0, fontWeight: 0, lineHeight: 0, letterSpacing: 0, fontFamily: 0 };
const skipped = [];
const weightErrors = new Set();
let autoLineHeights = 0;

for (const node of [...g.nodes.values()]) {
  if (node.type !== 'TEXT' || inInstance(node)) continue;
  results.nodes++;
  const set = setAncestor(node);
  const tr = typeRow(node);

  if (node.lineHeight == null) {
    const fs = node.fontSize, fw = node.fontWeight;
    const lh = fs === 12 ? (fw === 600 ? 18 : 16) : fs === 13 ? 20 : fs === 14 ? 20 : fs === 16 ? 24 : null;
    if (lh != null) { g.updateNode(node.id, { lineHeight: lh }); autoLineHeights++; }
  }
  const n = g.getNode(node.id);

  const binds = [
    ['fontSize', pickSize(n, set, tr), n.fontSize],
    ['lineHeight', pickLineHeight(n, set, tr), n.lineHeight],
    ['letterSpacing', pickTracking(n), n.letterSpacing],
    ['fontFamily', pickFamily(n), n.fontFamily],
  ];
  for (const [field, name, value] of binds) {
    if (!name) { skipped.push({ id: n.id, field, reason: 'no token', value }); continue; }
    if (!matches(name, field, value)) { skipped.push({ id: n.id, field, name, reason: 'value mismatch', value, varValue: valueOf(name) }); continue; }
    try { g.bindVariable(n.id, field, byName.get(name).id); results[field]++; }
    catch (e) { skipped.push({ id: n.id, field, name, reason: String(e) }); }
  }

  const wName = pickWeight(n, set, tr);
  if (wName && matches(wName, 'fontWeight', n.fontWeight)) {
    try { g.bindVariable(n.id, 'fontWeight', byName.get(wName).id); results.fontWeight++; }
    catch (e) { weightErrors.add(String(e)); }
  }
}

return {
  results,
  autoLineHeights,
  skippedCount: skipped.length,
  skipped: skipped.slice(0, 40),
  weightErrors: [...weightErrors],
  collections: [...g.variableCollections.values()].map((c) => ({ name: c.name, vars: c.variableIds.length })),
};

