const g = figma.graph;
const collections = [...g.variableCollections.values()];
const byName = new Map();
for (const v of g.variables.values()) byName.set(v.name, v);

function modeId(collectionName, modeName) {
  const c = collections.find((x) => x.name === collectionName);
  return c?.modes.find((m) => m.name === modeName)?.modeId;
}
const semLight = modeId('Semantic', 'Light');
const compLight = modeId('Component', 'Light');
const colorVars = [...g.variables.values()].filter((v) => v.type === 'COLOR');
const lightMap = new Map();
for (const v of colorVars) {
  const val = v.valuesByMode[semLight] ?? v.valuesByMode[compLight] ?? Object.values(v.valuesByMode)[0];
  if (!val || typeof val !== 'object' || !('r' in val)) continue;
  const key = `${val.r.toFixed(4)},${val.g.toFixed(4)},${val.b.toFixed(4)},${val.a.toFixed(4)}`;
  if (!lightMap.has(key)) lightMap.set(key, []);
  lightMap.get(key).push(v.name);
}
const keyOf = (c) => `${c.r.toFixed(4)},${c.g.toFixed(4)},${c.b.toFixed(4)},${c.a.toFixed(4)}`;

function ancestors(n) {
  const out = [];
  let p = n, d = 0;
  while (p && d++ < 30) { out.push(p); p = p.parentId ? g.getNode(p.parentId) : null; }
  return out;
}
function isDark(n) { return ancestors(n).some((p) => typeof p.name === 'string' && /Dark/.test(p.name)); }
function inComponent(n) { return ancestors(n).some((p) => p.type === 'COMPONENT' || p.type === 'COMPONENT_SET' || p.type === 'INSTANCE'); }
function inBaseChip(n) { return ancestors(n).some((p) => typeof p.name === 'string' && p.name.startsWith('base ')); }
function first(candidates, priority) {
  for (const name of priority) if (candidates.includes(name)) return name;
  return null;
}
function pick(n, candidates, field, set) {
  if (!candidates.length) return null;
  if (n.type === 'TEXT') {
    return first(candidates, ['color.text.primary', 'color.text.secondary', 'color.text.onPrimary', 'control.foreground', 'input.foreground', 'label.foreground', 'menu.foreground', 'button.foreground', 'color.primary', 'color.accent']);
  }
  if (field.startsWith('strokes/')) {
    return first(candidates, ['color.border', 'color.separator', 'control.border', 'input.border', 'button.border', 'menu.border', 'color.primary', 'color.accent', 'slider.track', 'toggle.track.off', 'progress.track', 'gauge.track']);
  }
  const nm = n.name || '';
  if (/Bar|Sample|Chip|Swatch/.test(nm)) return first(candidates, ['color.primary', 'color.accent', 'color.surface', 'color.background', 'control.background.hover']);
  if (set === 'Progress') return first(candidates, ['progress.fill', 'color.primary']);
  if (set === 'Gauge') return first(candidates, ['gauge.fill', 'color.primary']);
  if (set === 'Slider') return first(candidates, ['slider.accent', 'slider.track', 'slider.thumb', 'color.primary']);
  return first(candidates, ['color.background', 'color.surface', 'control.background', 'input.background', 'button.background', 'menu.background', 'stepper.background', 'control.background.hover', 'color.primary', 'color.accent']);
}
function setAncestor(n) {
  const a = ancestors(n).find((p) => p.type === 'COMPONENT_SET');
  return a ? a.name : '';
}

const results = { bound: 0, skippedBound: 0, unmatched: 0, noPriority: 0 };
const unmatched = {};
const noPriority = {};

// base palette chips first
for (const item of [...g.nodes.values()]) {
  if (isDark(item) || item.type !== 'FRAME' || !/^base /.test(item.name || '')) continue;
  const chip = item.childIds.map((id) => g.getNode(id)).find((c) => c.type === 'FRAME' && c.name === 'Chip');
  if (!chip) continue;
  const label = item.childIds.map((id) => g.getNode(id)).find((c) => c.type === 'TEXT');
  const varName = label?.characters?.trim();
  const v = varName ? byName.get(varName) : null;
  if (v && v.type === 'COLOR' && chip.fills?.[0] && !chip.boundVariables?.['fills/0/color']) {
    g.bindVariable(chip.id, 'fills/0/color', v.id);
    results.bound++;
  }
}

for (const n of [...g.nodes.values()]) {
  if (n.type === 'INSTANCE' || isDark(n) || inComponent(n) || inBaseChip(n)) continue;
  const set = setAncestor(n);
  const b = n.boundVariables || {};
  const check = (paints, kind) => {
    for (let i = 0; i < (paints || []).length; i++) {
      const paint = paints[i];
      if (paint.type !== 'SOLID' || paint.visible === false) continue;
      const field = `${kind}/${i}/color`;
      if (b[field]) { results.skippedBound++; continue; }
      const key = keyOf(paint.color);
      const candidates = lightMap.get(key) || [];
      if (!candidates.length) { results.unmatched++; unmatched[key] = (unmatched[key] || 0) + 1; continue; }
      const name = pick(n, candidates, field, set);
      if (!name) { results.noPriority++; noPriority[key] = (noPriority[key] || 0) + 1; continue; }
      g.bindVariable(n.id, field, byName.get(name).id);
      results.bound++;
    }
  };
  check(n.fills, 'fills');
  check(n.strokes, 'strokes');
}

return { results, unmatched, noPriority, lightVarCount: colorVars.length };

const g = figma.graph;
const collections = [...g.variableCollections.values()];
const sem = collections.find((c) => c.name === 'Semantic');
const comp = collections.find((c) => c.name === 'Component');
const lightId = sem.modes.find((m) => m.name === 'Light').modeId;
const semDark = sem.modes.find((m) => m.name === 'Dark').modeId;
const compLight = comp.modes.find((m) => m.name === 'Light').modeId;
const compDark = comp.modes.find((m) => m.name === 'Dark').modeId;

function setMode(id, mode) {
  g.updateNode(id, { variableModes: { [sem.id]: mode === 'Dark' ? semDark : lightId, [comp.id]: mode === 'Dark' ? compDark : compLight } });
}
function clearBindings(node, failures) {
  const b = node.boundVariables || {};
  for (const field of Object.keys(b)) {
    try { g.unbindVariable(node.id, field); }
    catch (e) { failures.push({ node: node.id, field, error: String(e) }); }
  }
  for (const cid of node.childIds) clearBindings(g.getNode(cid), failures);
}
function copyPair(l, d, path, stats, failures) {
  const b = l.boundVariables || {};
  for (const [field, id] of Object.entries(b)) {
    try { g.bindVariable(d.id, field, id); stats.copied++; }
    catch (e) { failures.push({ path, field, error: String(e) }); }
  }
  const lc = l.childIds.map((id) => g.getNode(id));
  const dc = d.childIds.map((id) => g.getNode(id));
  if (lc.length !== dc.length) failures.push({ path, error: `child count ${lc.length} vs ${dc.length}` });
  for (let i = 0; i < Math.min(lc.length, dc.length); i++) copyPair(lc[i], dc[i], `${path}/${i}:${lc[i].name}`, stats, failures);
}

const pairs = [];
const byName = new Map();
for (const n of g.nodes.values()) {
  if (!byName.has(n.name)) byName.set(n.name, []);
  byName.get(n.name).push(n);
}

// component roots (sets + standalone components)
for (const d of [...g.nodes.values()]) {
  if (!(d.type === 'COMPONENT_SET' || d.type === 'COMPONENT')) continue;
  if (!d.name.endsWith(' Dark')) continue;
  if (d.parentId && g.getNode(d.parentId)?.type === 'COMPONENT_SET') continue;
  const lightName = d.name.slice(0, -5);
  const l = (byName.get(lightName) || []).find((x) => x.type === d.type);
  if (l) pairs.push({ kind: 'component', light: l, dark: d });
  else pairs.push({ kind: 'missing-light', dark: d });
}
// theme panels
for (const d of [...g.nodes.values()]) {
  if (d.type !== 'FRAME' || d.name !== 'Dark panel') continue;
  const parent = d.parentId ? g.getNode(d.parentId) : null;
  const l = parent ? parent.childIds.map((id) => g.getNode(id)).find((x) => x.name === 'Light panel') : null;
  if (l) pairs.push({ kind: 'panel', light: l, dark: d });
  else pairs.push({ kind: 'missing-light', dark: d });
}
// showcase boards
{
  const l = (byName.get('Showcase Light') || [])[0];
  const d = (byName.get('Showcase Dark') || [])[0];
  if (l && d) pairs.push({ kind: 'board', light: l, dark: d });
}
// foundations palettes
{
  const l = (byName.get('light palette') || [])[0];
  const d = (byName.get('dark palette') || [])[0];
  if (l && d) pairs.push({ kind: 'palette', light: l, dark: d });
}

const stats = { pairs: pairs.length, copied: 0, cleared: 0 };
const failures = [];
for (const p of pairs) {
  if (!p.light) { failures.push({ kind: p.kind, dark: p.dark.id, error: 'no light counterpart' }); continue; }
  // clear stale bindings in the dark subtree
  clearBindings(p.dark, failures);
  copyPair(p.light, p.dark, `${p.kind}:${p.light.name}`, stats, failures);
  setMode(p.dark.id, 'Dark');
  setMode(p.light.id, 'Light');
}
// page roots light; outer showcase light
for (const root of [...g.nodes.values()]) {
  if (root.type === 'FRAME' && (root.name === 'Foundations' || root.name === 'Component library' || root.name === 'Showcase')) setMode(root.id, 'Light');
}
// explicit light/dark roots already set above; count nodes with modes
let darkNodes = 0, lightNodes = 0;
for (const n of g.nodes.values()) {
  const m = n.variableModes || {};
  if (m[sem.id] === semDark) darkNodes++;
  if (m[sem.id] === lightId) lightNodes++;
}
return { stats, failures: failures.slice(0, 30), failureCount: failures.length, darkNodes, lightNodes, pairKinds: pairs.map((p) => p.kind) };

