const g = figma.graph;
const byName = new Map();
for (const v of g.variables.values()) byName.set(v.name, v);
function bind(node, field, token) {
  const v = byName.get(token);
  if (!v) return { ok: false, reason: 'missing ' + token };
  if (node.boundVariables && node.boundVariables[field]) return { ok: false, reason: 'already bound' };
  try { g.bindVariable(node.id, field, v.id); return { ok: true }; }
  catch (e) { return { ok: false, reason: String(e) }; }
}
function inInstance(n) { let p = n, d = 0; while (p && d++ < 30) { if (p.type === 'INSTANCE') return true; p = p.parentId ? g.getNode(p.parentId) : null; } return false; }
function children(n) { return n.childIds.map((id) => g.getNode(id)); }
function baseName(name) { return name.replace(/ Dark$/, ''); }
function isVariantRoot(n) { return n.type === 'COMPONENT' && (!n.parentId || g.getNode(n.parentId)?.type !== 'COMPONENT_SET'); }
function isVariant(n) { return n.type === 'COMPONENT' && n.parentId && g.getNode(n.parentId)?.type === 'COMPONENT_SET'; }

const radiusMap = { 2: 'radius.xs', 6: 'radius.sm', 8: 'radius.lg', 12: 'radius.xl', 9999: 'radius.full', 16: 'base.radius.2xl' };
const strokeMap = { 1: 'border.width.thin', 2: 'border.width.thick', 3: 'base.border.width.3' };
const stats = { bound: 0, skipped: 0, errors: [] };
function tryBind(node, field, token) {
  const r = bind(node, field, token);
  if (r.ok) stats.bound++;
  else if (r.reason !== 'already bound') stats.errors.push({ id: node.id, field, token, reason: r.reason });
  else stats.skipped++;
}
function bindSize(node, token, field = 'height') {
  const tok = byName.get(token); if (!tok) return;
  const val = Object.values(tok.valuesByMode)[0];
  if (Math.abs(node[field] - val) > 0.001) return;
  tryBind(node, field, token);
}
function bindRadius(node, field, value) {
  let token = radiusMap[value];
  if (value === 3) token = /Checkbox/.test(node.name || '') ? 'toggle.checkbox.radius' : 'base.radius.3';
  if (value === 4) token = /Swatch/.test(node.name || '') ? 'color.swatch.radius' : 'base.radius.4';
  if (token) tryBind(node, field, token);
}

// ── component-specific dimensions/radii/strokes ─────────────────────────────
function processComponent(root, setBase) {
  const walk = (n) => {
    const b = n.boundVariables || {};
    const nm = n.name || '';
    switch (setBase) {
      case 'Button':
        if (isVariant(n) || isVariantRoot(n)) bindSize(n, 'control.height');
        break;
      case 'TextField':
        if (nm === 'Input') bindSize(n, 'control.height');
        break;
      case 'Select': case 'Date': case 'Color':
        if (isVariant(n) || isVariantRoot(n)) bindSize(n, 'control.height');
        break;
      case 'Menu':
        if (nm === 'Trigger') bindSize(n, 'control.height');
        if (nm === 'Popover') {
          if (n.width !== 160) g.updateNode(n.id, { width: 160 });
          bindSize(n, 'menu.min-width', 'width');
          tryBind(n, 'cornerRadius', 'menu.radius');
          tryBind(n, 'strokeWeight', 'menu.border.width');
        }
        break;
      case 'Switch':
        if (isVariant(n) || isVariantRoot(n)) {
          bindSize(n, 'toggle.switch.width', 'width');
          bindSize(n, 'toggle.switch.height');
          if (/Focus/.test(nm)) tryBind(n, 'strokeWeight', 'toggle.focus.ring.width');
        }
        if (nm === 'Thumb') { bindSize(n, 'toggle.thumb.size', 'width'); bindSize(n, 'toggle.thumb.size'); }
        break;
      case 'Checkbox':
        if (isVariant(n) || isVariantRoot(n)) {
          bindSize(n, 'toggle.checkbox.size', 'width'); bindSize(n, 'toggle.checkbox.size');
          tryBind(n, 'cornerRadius', 'toggle.checkbox.radius');
        }
        break;
      case 'Slider':
        if (isVariant(n) || isVariantRoot(n)) bindSize(n, 'slider.height');
        if (nm === 'Track') { bindSize(n, 'slider.track.height'); tryBind(n, 'cornerRadius', 'slider.track.radius'); }
        if (nm === 'Thumb') {
          bindSize(n, 'slider.thumb.size', 'width'); bindSize(n, 'slider.thumb.size');
          tryBind(n, 'cornerRadius', 'slider.track.radius');
          tryBind(n, 'strokeWeight', 'slider.thumb.border.width');
        }
        break;
      case 'Progress': case 'Gauge': {
        const h = setBase === 'Progress' ? 'progress.height' : 'gauge.height';
        const r = setBase === 'Progress' ? 'progress.radius' : 'gauge.radius';
        if (isVariant(n) || isVariantRoot(n) || nm === 'Fill') bindSize(n, h);
        if (isVariant(n) || isVariantRoot(n)) tryBind(n, 'cornerRadius', r);
        break;
      }
      case 'Spinner':
        if (isVariant(n) || isVariantRoot(n) || n.type === 'ELLIPSE') { bindSize(n, 'spinner.size', 'width'); bindSize(n, 'spinner.size'); }
        if (n.type === 'ELLIPSE') tryBind(n, 'strokeWeight', 'spinner.border.width');
        break;
      case 'Stepper':
        if (nm === 'Button') { bindSize(n, 'stepper.button.size', 'width'); bindSize(n, 'stepper.button.size'); tryBind(n, 'cornerRadius', 'stepper.radius'); }
        break;
    }
    for (const c of children(n)) walk(c);
  };
  walk(root);
}

for (const root of [...g.nodes.values()]) {
  if (inInstance(root)) continue;
  if (root.type === 'COMPONENT_SET') {
    const base = baseName(root.name);
    for (const v of children(root)) processComponent(v, base);
  } else if (root.type === 'COMPONENT' && isVariantRoot(root)) {
    processComponent(root, baseName(root.name));
  }
}

// ── generic radii, strokes, opacity on every non-instance node ───────────────
for (const n of [...g.nodes.values()]) {
  if (inInstance(n)) continue;
  const b = n.boundVariables || {};
  if (typeof n.cornerRadius === 'number' && n.cornerRadius > 0 && !b.cornerRadius) bindRadius(n, 'cornerRadius', n.cornerRadius);
  if (n.independentCorners) {
    for (const f of ['topLeftRadius', 'topRightRadius', 'bottomLeftRadius', 'bottomRightRadius']) {
      if (typeof n[f] === 'number' && n[f] > 0 && !b[f]) bindRadius(n, f, n[f]);
    }
  }
  if (Array.isArray(n.strokes) && n.strokes.length > 0 && typeof n.strokeWeight === 'number' && n.strokeWeight > 0 && !b.strokeWeight) {
    const token = strokeMap[n.strokeWeight];
    if (token) tryBind(n, 'strokeWeight', token);
  }
  if (typeof n.opacity === 'number' && n.opacity < 1 && !b.opacity) {
    const tok = byName.get('opacity.disabled');
    if (tok && Math.abs(tok.valuesByMode[Object.keys(tok.valuesByMode)[0]] - n.opacity) < 0.001) tryBind(n, 'opacity', 'opacity.disabled');
  }
}

return { stats };

