const g = figma.graph; let n=0;
for (const v of g.variables.values()) {
  if (!v.description || v.description.includes('dtcg type')) continue;
  let hint = null;
  if (v.type === 'FLOAT') {
    if (/weight/.test(v.name) || /(^|\.)z\./.test(v.name) || /opacity/.test(v.name)) hint = 'number';
    else if (/duration/.test(v.name)) hint = 'duration';
  } else if (v.type === 'STRING' && /family/.test(v.name)) {
    hint = 'fontFamily';
  }
  if (hint) { v.description = `${v.description}; dtcg type ${hint}`; n++; }
}
return { updated: n, sample: [...g.variables.values()].filter(v=>/weight|family|opacity|duration|z\./.test(v.name)).slice(0,10).map(v=>({name:v.name,description:v.description})) };
EOF
