const g=figma.graph;
function inInst(n){let p=n,d=0;while(p&&d++<35){if(p.type==='INSTANCE')return true;p=p.parentId?g.getNode(p.parentId):null;}return false;}
const cols=[...g.variableCollections.values()].map(c=>({name:c.name,modes:c.modes.map(m=>m.name),vars:c.variableIds.length}));
const bound={}; const unbound={radius:0,stroke:0,opacity:0,fontSize:0,lineHeight:0,letterSpacing:0,fontFamily:0,fontWeight:0};
let darkModeNodes=0, lightModeNodes=0, stale=0;
for(const n of [...g.nodes.values()]){
  const b=n.boundVariables||{};
  for(const k of Object.keys(b)) { bound[k]=(bound[k]||0)+1; if(!g.variables.has(b[k])) stale++; }
  if(n.variableModes&&Object.keys(n.variableModes).length){ /* count later */ }
  if(inInst(n))continue;
  if(n.type==='TEXT'){for(const f of ['fontSize','lineHeight','letterSpacing','fontFamily','fontWeight']) if(!b[f]) unbound[f]++;}
  if(typeof n.cornerRadius==='number'&&n.cornerRadius>0&&!b.cornerRadius)unbound.radius++;
  if(Array.isArray(n.strokes)&&n.strokes.length&&n.strokeWeight>0&&!b.strokeWeight)unbound.stroke++;
  if(typeof n.opacity==='number'&&n.opacity<1&&!b.opacity)unbound.opacity++;
}
const byKey=(arr)=>arr.reduce((o,k)=>{o[k]=(o[k]||0)+1;return o;},{});
return {collections:cols, boundCounts:byKey(Object.keys(bound)), totalBound:Object.values(bound).reduce((a,b)=>a+b,0), unbound, stale, componentSets:[...g.nodes.values()].filter(n=>n.type==='COMPONENT_SET').length, components:[...g.nodes.values()].filter(n=>n.type==='COMPONENT').length, instances:[...g.nodes.values()].filter(n=>n.type==='INSTANCE').length, pages:g.getPages().map(p=>p.name)};
EOF
